select count(*) as total_rows,count(*) filter (where installation_id is not null) as canonical_rows,count(*) filter (where installation_id is null) as legacy_rows,count(distinct user_id) filter (where installation_id is not null) as users_with_canonical_installation,count(distinct user_id) filter (where installation_id is null) as users_with_legacy_rows from public.push_tokens;
select user_id,count(*) filter (where installation_id is not null) as canonical_installations,count(*) filter (where installation_id is null) as legacy_tokens,max(last_seen_at) as last_seen_at from public.push_tokens group by user_id order by legacy_tokens desc,canonical_installations desc;
